"""Embed the self-contained mobile page in the Arduino sketch's flash header."""
from pathlib import Path

root = Path(__file__).resolve().parents[1] / "firmware/kenny_mobile"
page = (root / "web/index.html").read_text()
assert ')KENNYHTML"' not in page
(root / "web_ui.h").write_text(
    '// Generated by scripts/build_mobile_ui.py; edit web/index.html instead.\n'
    '#pragma once\n#include <pgmspace.h>\n'
    'static const char KENNY_WEB_UI[] PROGMEM = R"KENNYHTML(' + page + ')KENNYHTML";\n')
print("Embedded mobile UI:", len(page.encode()), "bytes")
